  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late Future<(List<CurrencyModel>, List<NewsModel>)> _loadDataFuture;

  @override
  void initState() {
    super.initState();
    _loadDataFuture = _initData();
  }

  static Future<List<dynamic>> _fetchAllRaw(
    CurrencyRepository currencyRepo,
    NewsRepository newsRepo,
  ) async {
    return Future.wait([
      currencyRepo.fetchRates(const CurrencyPageRequest(base: 'USD')),
      newsRepo.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]);
  }

  static Future<(List<CurrencyModel>, List<NewsModel>)> _fetchAll(
    CurrencyRepository currencyRepo,
    NewsRepository newsRepo,
  ) async {
    final List<dynamic> results = await _fetchAllRaw(currencyRepo, newsRepo);
    final CurrencyPage page = results[0] as CurrencyPage;
    final List<NewsModel> newsList = results[1] as List<NewsModel>;
    return (page.items, newsList);
  }

  Future<(List<CurrencyModel>, List<NewsModel>)> _initData() async {
    final CurrencyRepository currencyRepo = context.read<CurrencyRepository>();
    final NewsRepository newsRepo = context.read<NewsRepository>();

    return _fetchAll(currencyRepo, newsRepo);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.dashboard)),
      body: FutureBuilder<(List<CurrencyModel>, List<NewsModel>)>(
        future: _loadDataFuture,
        builder: (BuildContext context,
            AsyncSnapshot<(List<CurrencyModel>, List<NewsModel>)> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting ||
              !snapshot.hasData) {
            return const Center(child: CircularProgressIndicator());
          }

          if (snapshot.hasError) {
            return Center(
              child: Text(snapshot.error.toString()),
            );
          }

          final List<CurrencyModel> currencies = snapshot.data!.$1;
          final List<NewsModel> news = snapshot.data!.$2;

          return Column(
            children: [
              Expanded(
                child: ListView.builder(
                  itemCount: currencies.length,
                  itemBuilder: (BuildContext context, int index) {
                    if (index == 0 && currencies.isNotEmpty) {
                      return const Padding(
                        padding: EdgeInsets.only(top: 20),
                        child: Divider(),
                      );
                    }
                    final CurrencyModel currency = currencies[index];
                    return Padding(
                      key: ValueKey(currency.id),
                      padding: const EdgeInsets.symmetric(
                          vertical: 8, horizontal: 16),
                      child: Text('${currency.name}: ${currency.value}'),
                    );
                  },
                ),
              ),
              const Divider(thickness: 2),
              Expanded(
                child: ListView.builder(
                  itemCount: news.length,
                  itemBuilder: (BuildContext context, int index) {
                    if (index == 0 && news.isNotEmpty) {
                      return const Padding(
                        padding: EdgeInsets.only(top: 16),
                        child: Divider(),
                      );
                    }
                    final NewsModel n = news[index];
                    return Padding(
                      key: ValueKey(n.link),
                      padding: const EdgeInsets.symmetric(
                          vertical: 8, horizontal: 16),
                      child: Text(n.title),
                    );
                  },
                ),
              ),
            ],
          );
        },
      ),
    );
  }
}
