import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  group('DashboardPage', () {
    testWidgets('should show progress indicator while loading', (WidgetTester tester) async {
      final MockCurrencyRepository mockCurrencyRepo = MockCurrencyRepository();
      final MockNewsRepository mockNewsRepo = MockNewsRepository();

      // Оставляем future незавершённым — индикатор должен отображаться.
      when(
        mockCurrencyRepo.fetchRates(const CurrencyPageRequest(base: 'USD')),
      ).thenAnswer((_) async => throw Exception('delay'));

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepo),
            Provider<NewsRepository>.value(value: mockNewsRepo),
          ],
          child: const DashboardPage(),
        ),
      );

      expect(find.byType(CircularProgressIndicator), findsOneWidget);
    });

    testWidgets('should display dashboard title and data after loading', (WidgetTester tester) async {
      final MockCurrencyRepository mockCurrencyRepo = MockCurrencyRepository();
      final MockNewsRepository mockNewsRepo = MockNewsRepository();

      when(
        mockCurrencyRepo.fetchRates(const CurrencyPageRequest(base: 'USD')),
      ).thenAnswer(
        (_) => Future<CurrencyPage>.value(
          const CurrencyPage(
            items: [
              CurrencyModel(
                id: '1',
                nominal: 1,
                name: 'USD',
                symbol: r'\$',
                value: 78.5,
                previousValue: 78.0,
              ),
            ],
            page: 0,
            hasMore: false,
          ),
        ),
      );

      when(mockNewsRepo.loadNewsFeed(any)).thenAnswer(
        (_) => Future<List<NewsModel>>.value(
          const [
            NewsModel(title: 'Test News', link: 'https://example.com'),
          ],
        ),
      );

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepo),
            Provider<NewsRepository>.value(value: mockNewsRepo),
          ],
          child: const DashboardPage(),
        ),
      );

      // Ожидаем завершения Future.wait и перестроения виджетов.
      await tester.pumpAndSettle();

      expect(find.text('Дашборд'), findsOneWidget);
      expect(find.text('USD: 78.5'), findsOneWidget);
      expect(find.text('Test News'), findsOneWidget);
    });
  });
}

